/* Prototipe UI pendukung PRD. Seluruh data simulasi, tidak terhubung ke server. */
(function(){
  const APP_KEY='smkprd-demo-';
  const defaults=['surat','website'];
  const names=[['pkl','PKL'],['jurnal','Jurnal Guru'],['absensi','Absensi & Perizinan'],['surat','Administrasi Surat'],['keuangan','Keuangan & SPP'],['bkk','BKK & Lowongan'],['inventaris','Inventaris & Sarpras'],['bk','Bimbingan Konseling'],['jadwal','Jadwal Pelajaran'],['tracer','Tracer Study Alumni'],['hubin','HUBIN / DUDI'],['supervisi','Supervisi Guru'],['laboratorium','Laboratorium & Bengkel'],['pelanggaran','Poin Pelanggaran'],['website','Website Sekolah']];
  const storage={get(k,fallback){try{const v=localStorage.getItem(APP_KEY+k);return v?JSON.parse(v):fallback;}catch(e){return fallback;}},set(k,v){try{localStorage.setItem(APP_KEY+k,JSON.stringify(v));}catch(e){}}};
  const $=sel=>document.querySelector(sel),$$=sel=>[...document.querySelectorAll(sel)];
  const escape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function toast(message,isError=false){const area=$('#toast-area');if(!area)return;let n=document.createElement('div');n.className='toast'+(isError?' error':'');n.textContent=message;area.append(n);setTimeout(()=>n.remove(),4300);}
  function closeModal(){const overlay=$('#modal-backdrop');if(!overlay)return;overlay.classList.remove('open');overlay.innerHTML='';document.body.style.overflow='';}
  function modal({title,content='',confirmText='Konfirmasi',cancelText='Batal',onConfirm=null,wide=false,closable=true,danger=false,footer=true}){
    const overlay=$('#modal-backdrop');if(!overlay)return;
    overlay.classList.add('open');overlay.innerHTML=`<div class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><h2 id="dialog-title">${escape(title)}</h2>${closable?'<button type="button" class="modal-close" data-close aria-label="Tutup">✕</button>':''}</div><div id="dialog-content">${content}</div>${footer?`<div class="modal-actions"><button class="btn btn-outline" type="button" data-close>${escape(cancelText)}</button><button class="btn ${danger?'btn-danger':'btn-accent'}" id="modal-confirm" type="button">${escape(confirmText)}</button></div>`:''}</div>`;
    document.body.style.overflow='hidden';overlay.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
    overlay.onclick=e=>{if(e.target===overlay&&closable)closeModal();};
    const confirm=$('#modal-confirm');if(confirm)confirm.onclick=()=>{if(!onConfirm){closeModal();return;}const original=overlay.querySelector('.modal');const result=onConfirm();if(result!==false && overlay.querySelector('.modal')===original)closeModal();};
    const focus=overlay.querySelector('button');if(focus)focus.focus();return overlay;
  }
  function confirmAction(title,message,onConfirm,button='Ya, lanjutkan',danger=false){modal({title,content:`<p>${escape(message)}</p>`,confirmText:button,danger,onConfirm});}
  function setBusy(button,yes,txt='Memproses…'){if(!button)return;if(yes){button.dataset.oldText=button.innerHTML;button.disabled=true;button.innerHTML='<span aria-hidden="true">◌</span> '+escape(txt);}else{button.disabled=false;button.innerHTML=button.dataset.oldText||button.innerHTML;}}
  // Progress simulasi: setiap item hanya dihitung selesai setelah worker menyelesaikannya.
  function simulateBulk({title,total=60,failAt=[],skipAt=[],onDone=null,key='default',warning=''}){
    const jobId='job-'+key;
    const old=storage.get(jobId,null);
    let stats=(old&&old.total===total&&old.finished<total)?old:{total,finished:0,success:0,failed:0,skipped:0,paused:false};
    stats.paused=true;storage.set(jobId,stats);
    const html=`<p>Simulasi UI batch HTTP paralel (maksimal 3 proses bersamaan). Tidak mengubah database sekolah.</p>${warning?`<div class="note">${escape(warning)}</div>`:''}<div class="spread" style="margin:20px 0 8px"><strong id="bulk-percent" style="font-size:26px">${Math.round(stats.finished*100/stats.total)}%</strong><span id="bulk-count" class="muted small">${stats.finished} / ${total} selesai</span></div><div class="progress-track" role="progressbar" aria-label="Progres proses massal" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" id="bulk-track"><div class="progress-fill" id="bulk-fill" style="width:${stats.finished*100/stats.total}%"></div></div><div class="grid grid-3" style="margin-top:15px"><div class="panel panel-pad"><div class="muted tiny">BERHASIL</div><strong id="bulk-success">${stats.success}</strong></div><div class="panel panel-pad"><div class="muted tiny">GAGAL</div><strong id="bulk-failed">${stats.failed}</strong></div><div class="panel panel-pad"><div class="muted tiny">DILEWATI</div><strong id="bulk-skipped">${stats.skipped}</strong></div></div><p class="small" id="bulk-state">Siap diproses.</p><div class="modal-actions"><button class="btn btn-outline" id="bulk-pause">Jeda</button><button class="btn btn-accent" id="bulk-start">${stats.finished?'Lanjutkan proses':'Mulai proses'}</button></div>`;
    modal({title,content:html,closable:false,footer:false,wide:true});
    let pointer=stats.finished, running=false,paused=false, inflight=0,ended=false;
    function refresh(){const p=Math.round(stats.finished*100/stats.total);$('#bulk-percent').textContent=p+'%';$('#bulk-count').textContent=stats.finished+' / '+total+' selesai';$('#bulk-fill').style.width=p+'%';$('#bulk-track').setAttribute('aria-valuenow',p);$('#bulk-success').textContent=stats.success;$('#bulk-failed').textContent=stats.failed;$('#bulk-skipped').textContent=stats.skipped;storage.set(jobId,stats);}
    function completion(){if(ended||stats.finished<total||inflight>0)return;ended=true;storage.set(jobId,stats);const summary=`<p>Seluruh ${total} item sudah mendapat hasil. Ini hanya simulasi interaksi frontend.</p><div class="grid grid-3"><div class="panel panel-pad"><div class="muted tiny">BERHASIL</div><h2>${stats.success}</h2></div><div class="panel panel-pad"><div class="muted tiny">GAGAL</div><h2>${stats.failed}</h2></div><div class="panel panel-pad"><div class="muted tiny">DILEWATI</div><h2>${stats.skipped}</h2></div></div>${stats.failed?'<p class="warn-text">Item gagal perlu diperiksa dan dicoba kembali berdasarkan status tersimpan.</p>':''}`;modal({title:'Ringkasan hasil proses',content:summary,confirmText:'Selesai',cancelText:'Tutup',onConfirm:()=>{storage.set(jobId,null);if(onDone)onDone(stats);},wide:true});}
    function next(){if(paused||!running)return;while(inflight<3&&pointer<total&&!paused){let index=pointer++;inflight++;setTimeout(()=>{inflight--;stats.finished++;if(failAt.includes(index))stats.failed++;else if(skipAt.includes(index))stats.skipped++;else stats.success++;refresh();completion();next();},80+(index%4)*45);}if(paused&&inflight===0){$('#bulk-state').textContent='Dijeda — hasil yang sudah selesai tetap tersimpan.';}if(pointer>=total&&inflight===0)completion();}
    $('#bulk-start').onclick=()=>{if(running){paused=false;$('#bulk-state').textContent='Melanjutkan proses…';next();return;}running=true;paused=false;$('#bulk-start').textContent='Lanjutkan';$('#bulk-state').textContent='Memproses dalam beberapa batch paralel…';next();};
    $('#bulk-pause').onclick=()=>{paused=true;$('#bulk-state').textContent='Menjeda setelah proses berjalan selesai…';};
    return {stats};
  }
  function initNav(){const menu=$('#mobile-menu'),sidebar=$('#sidebar'),back=$('#sidebar-backdrop');if(menu){menu.onclick=()=>{sidebar.classList.toggle('open');back.classList.toggle('open');};back.onclick=()=>{sidebar.classList.remove('open');back.classList.remove('open');};}document.addEventListener('keydown',e=>{if(e.key==='Escape'){const over=$('#modal-backdrop');if(over?.classList.contains('open')&&over.querySelector('[data-close]'))closeModal();}});}
  function initGeneric(){ $$('[data-toast]').forEach(el=>el.addEventListener('click',()=>toast(el.dataset.toast)));$$('[data-action-confirm]').forEach(el=>el.addEventListener('click',()=>confirmAction(el.dataset.actionConfirm,el.dataset.message||'Apakah Anda yakin?',()=>toast('Perubahan berhasil disimpan (simulasi).'),el.dataset.confirmText||'Lanjutkan',el.dataset.danger==='true')));$$('[data-demo-loading]').forEach(el=>el.addEventListener('click',()=>{setBusy(el,true,el.dataset.demoLoading||'Menyimpan…');setTimeout(()=>{setBusy(el,false);toast('Berhasil disimpan (simulasi).');},750);}));}
  window.SMK={storage,$,$$,escape,toast,modal,closeModal,confirmAction,setBusy,simulateBulk,moduleNames:names,getModules:()=>storage.get('activeModules',defaults),setModules:xs=>storage.set('activeModules',xs)};
  document.addEventListener('DOMContentLoaded',()=>{initNav();initGeneric();});
})();
